1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	
45	const policyBaseOf = (items: Item[]): number => {
46	  if (items.length === BLOCK_SIZE && items.every((item) => item.type === items[0].type)) {
47	    return BLOCK_BASE_PREMIUM;
48	  }
49	  return items.reduce((sum, item) => sum + basePremiumOf(item), 0);
50	};
51	
52	// Rounding always favours the MHPCO: premiums up, payouts down.
53	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
54	
55	const quoteFor = (items: Item[]): Result => {
56	  const policyBase = policyBaseOf(items);
57	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
58	  const premiumBeforeRounding = policyBase + firstInsuranceSurcharge + PROCESSING_FEE;
59	  return { premium: premiumRoundedInMHPCOsFavour(premiumBeforeRounding) };
60	};
61	
62	const resultFor = (step: Step): Result => {
63	  if (step.op === "quote") return quoteFor(step.items);
64	  throw new Error(`unsupported step: ${step.op}`);
65	};
66	
67	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
68	  results: scenario.steps.map(resultFor),
69	});
