const areAlike = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

const formsABuildingBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && areAlike(items);

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const policyBaseOf = (items: Item[]): number =>
  formsABuildingBlock(items) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(items);
